script:
# التحقق من الحقول الأساسية
if not doc.opportunity_type:
    frappe.throw("يجب تحديد نوع الفرصة / Opportunity Type is required")

if not doc.pipeline_am:
    frappe.throw("يجب تعيين Pipeline AM")

if not doc.assigned_to:
    frappe.throw("يجب تعيين المستخدم المسؤول / Assigned To is required")

if not doc.customer:
    frappe.throw("يجب تحديد العميل / Customer is required")

# التحقق من نوع الفرصة
if doc.opportunity_type == "Renewal" and not doc.expected_revenue:
    frappe.throw("يجب إدخال Expected Revenue لفرص التجديد")

# التحقق من الحقول الأساسية
if not doc.opportunity:
    frappe.throw("يجب ربط Qualification بفرصة بيع")

if not doc.qualified:
    frappe.throw("يجب تحديد نتيجة التأهيل")

if doc.qualified == "No" and not doc.reason_code:
    frappe.throw("يجب إدخال سبب عدم التأهيل")

if doc.ttm_volume is None:
    frappe.throw("يجب إدخال TTM Volume")

if doc.yoy_growth is None:
    frappe.throw("يجب إدخال YOY Growth %")

# التحقق من مجموع Airline Mix
total = (
    (doc.ms_percentage or 0) +
    (doc.sv_percentage or 0) +
    (doc.ek_percentage or 0) +
    (doc.np_percentage or 0) +
    (doc.ne_percentage or 0) +
    (doc.other_percentage or 0)
)

if total != 100:
    frappe.throw(f"مجموع Airline Mix = {total}% — يجب أن يكون 100% بالضبط")

# التحقق من الحقول الأساسية
if not doc.opportunity:
    frappe.throw("يجب ربط Business Case بفرصة بيع")

if not doc.customer:
    frappe.throw("يجب تحديد العميل")

if not doc.pipeline_am:
    frappe.throw("يجب تحديد Pipeline AM")

if not doc.commercial_proposal:
    frappe.throw("يجب إدخال Commercial Proposal")

if not doc.proposal_date:
    frappe.throw("يجب تحديد تاريخ الاقتراح")

# التحقق من Notes عند الرفض
if doc.status == "Rejected" and not doc.head_of_sales_notes:
    frappe.throw("يجب إدخال سبب الرفض في Head of Sales Notes")

# التحقق من الحقول الأساسية
if not doc.opportunity:
    frappe.throw("يجب ربط العقد بفرصة بيع")

if not doc.customer:
    frappe.throw("يجب تحديد العميل")

if not doc.contract_type:
    frappe.throw("يجب تحديد نوع العقد")

if not doc.contract_date:
    frappe.throw("يجب تحديد تاريخ العقد")

if not doc.start_date:
    frappe.throw("يجب تحديد تاريخ البداية")

if not doc.end_date:
    frappe.throw("يجب تحديد تاريخ الانتهاء")

# التحقق من التواريخ
if doc.start_date and doc.end_date:
    if doc.end_date <= doc.start_date:
        frappe.throw("تاريخ الانتهاء يجب أن يكون بعد تاريخ البداية")

# التحقق من Notes عند الرفض
if doc.head_of_sales_review == "Rejected" and not doc.notes:
    frappe.throw("يجب إدخال سبب الرفض في Notes")

# التحقق من الحقول الأساسية
if not doc.opportunity:
    frappe.throw("يجب ربط التنفيذ بفرصة بيع")

if not doc.customer:
    frappe.throw("يجب تحديد العميل")

if not doc.csm_assigned and not doc.flags.ignore_mandatory:
    frappe.throw("يجب تعيين CSM")

if not doc.implementation_date:
    frappe.throw("يجب تحديد تاريخ التنفيذ")

if not doc.status:
    frappe.throw("يجب تحديد حالة التنفيذ")

# التحقق من الحقول الأساسية
if not doc.opportunity:
    frappe.throw("يجب ربط Go-Live بفرصة بيع")

if not doc.customer:
    frappe.throw("يجب تحديد العميل")

if not doc.go_live_date:
    frappe.throw("يجب تحديد تاريخ Go-Live")

if not doc.status:
    frappe.throw("يجب تحديد الحالة")

# حساب تواريخ المتابعة تلقائياً
if doc.go_live_date:
    doc.follow_up_30_days = frappe.utils.add_days(doc.go_live_date, 30)
    doc.follow_up_60_days = frappe.utils.add_days(doc.go_live_date, 60)
    doc.follow_up_90_days = frappe.utils.add_days(doc.go_live_date, 90)
